\begin{proposition}[Topology of an Immersed Submanifold]
\label{exer:5-20}




\dcref{ch5:5.20}
Let $S\subseteq M$ be an immersed submanifold. Every subspace-open subset of
$S$ is open in its given manifold topology, and the converse holds exactly
when $S$ is embedded.
\end{proposition}

